/* ---------- SPIRITS ENCYCLOPEDIA ----------
   fields: n, base, origin, make, taste, styles, fact  (each [ko, en]) */
BAR.SPIRITS = [
 { id: 'gin', ic: '🌿', n: ['진', 'Gin'], base: ['곡물 중성 주정 + 주니퍼(노간주 열매)와 보태니컬', 'Neutral grain spirit + juniper and botanicals'],
   origin: ['네덜란드·벨기에의 주네버(제네버)에서 출발해 17–18세기 영국에서 폭발적으로 유행("진 광풍").', 'Grew out of Dutch/Belgian genever and exploded in 18th-century London (the "Gin Craze").'],
   make: ['중성 주정에 주니퍼, 코리앤더, 시트러스 껍질, 안젤리카 뿌리 등을 넣어 재증류하거나 향을 우려요. 주니퍼 향이 주인공이어야 "진".', 'Neutral spirit redistilled or infused with juniper, coriander, citrus peel, angelica root and more. Juniper must lead.'],
   taste: ['솔향·송진, 시트러스, 꽃, 흙내음. 드라이하고 상쾌.', 'Pine/resin, citrus, floral, earthy; dry and fresh.'],
   styles: ['런던 드라이: 지역이 아닌 제법. 증류 후 향료·색소 첨가 금지, 가장 드라이. / 올드 톰: 살짝 단 19세기 스타일(톰 콜린스의 원조). / 플리머스: 잉글랜드 플리머스의 한 증류소 스타일, 부드럽고 흙내음. / 주네버: 몰트 와인 기반, 위스키 같은 고소함 — 진의 조상.', 'London Dry: a method, not a place; nothing added after distillation; the driest. / Old Tom: lightly sweetened 19th-century style (the original Tom Collins gin). / Plymouth: a softer, earthier style from a single distillery in Plymouth, England. / Genever: malt-wine based, malty and bready; gin’s ancestor.'],
   fact: ['"더치 커리지(네덜란드식 용기)"는 전쟁터 병사들이 주네버를 마셨다는 이야기에서 나왔다는 설이 있어요(전설).', '"Dutch courage" is said to come from soldiers drinking genever before battle (a legend).'] },
 { id: 'vodka', ic: '❄️', n: ['보드카', 'Vodka'], base: ['곡물(밀·호밀) 또는 감자, 그 외 당분이 있는 원료', 'Grain (wheat, rye) or potato, or other fermentables'],
   origin: ['폴란드와 러시아가 서로 원조라고 주장해요. 폴란드 법원 기록에 1405년 "wódka"라는 말이 나와요. 결론은 미해결.', 'Poland and Russia both claim it. The word "wódka" appears in Polish court records in 1405. The debate is unresolved.'],
   make: ['연속식 증류기로 매우 높은 도수(약 95% 이상)까지 증류해 중성에 가깝게 만들고, 숯 등으로 여과한 뒤 물로 40% 안팎에 맞춰요.', 'Column-distilled to very high strength (about 95%+) for a near-neutral spirit, often charcoal-filtered, then cut with water to about 40%.'],
   taste: ['깨끗하고 중립적. 밀은 부드럽고 달콤, 호밀은 후추 같은 스파이스, 감자는 크리미한 질감.', 'Clean and neutral: wheat soft and sweet, rye peppery, potato creamy.'],
   styles: ['중성 보드카, 시트론 등 플레이버드 보드카, 감자 보드카, 호밀 보드카.', 'Neutral, flavoured (e.g. citron), potato, rye.'],
   fact: ['칵테일에서 보드카는 "도수와 질감"을 주고, 맛은 다른 재료가 주인공이 되게 해요.', 'In cocktails vodka adds strength and texture and lets the other ingredients speak.'] },
 { id: 'rum', ic: '🏝️', n: ['럼', 'Rum'], base: ['사탕수수: 당밀(대부분) 또는 생 사탕수수 즙', 'Sugarcane: molasses (most) or fresh cane juice'],
   origin: ['17세기 카리브해 사탕수수 농장에서 탄생(바베이도스가 초기 중심지로 꼽혀요). 영국 해군은 1970년까지 수병에게 럼을 배급했어요.', 'Born on 17th-century Caribbean sugar plantations (Barbados is often cited as an early centre). The Royal Navy issued a daily rum ration until 1970.'],
   make: ['설탕 생산 부산물인 당밀을 발효·증류. 단식(팟) 증류는 묵직하고, 연속식은 가벼워요. 열대 기후라 숙성이 빨라요.', 'Molasses, a by-product of sugar making, is fermented and distilled. Pot stills give heavy rums, columns light ones. The tropical heat speeds up ageing.'],
   taste: ['화이트: 가볍고 깨끗한 사탕수수 향 / 앰버·다크: 캐러멜, 바닐라, 바나나, 당밀 / 자메이카: 발효 향 진한 "펑키" 스타일.', 'White: light, clean cane / amber & dark: caramel, vanilla, banana, molasses / Jamaican: funky, high-ester.'],
   styles: ['화이트(라이트), 골드, 다크, 스파이스드. 럼 아그리콜: 프랑스령 카리브(마르티니크 등)에서 생 사탕수수 즙으로 만든 풀향 진한 럼. 브라질 카샤사도 사탕수수 즙 증류주.', 'White (light), gold, dark, spiced. Rhum agricole: grassy rum from fresh cane juice in the French Caribbean (e.g. Martinique). Brazil’s cachaça is also a cane-juice spirit.'],
   fact: ['같은 "다크 럼"이라도 오래 숙성했을 수도, 캐러멜로 색만 냈을 수도 있어요. 라벨을 읽는 습관!', '"Dark" can mean long-aged or just coloured with caramel. Read the label.'] },
 { id: 'tequila', ic: '🌵', n: ['테킬라 & 메스칼', 'Tequila & Mezcal'], base: ['아가베(용설란). 테킬라는 블루 웨버 아가베만', 'Agave. Tequila: blue Weber agave only'],
   origin: ['테킬라는 멕시코 할리스코 주(와 법으로 정한 4개 주 일부)에서만. 메스칼은 여러 아가베 품종으로 주로 오악사카에서.', 'Tequila comes from Jalisco (and set areas of four other states). Mezcal uses many agave species, mostly in Oaxaca.'],
   make: ['수년 자란 아가베의 심(피냐)을 익혀 당을 만들고, 짜서 발효·증류(보통 2회). 메스칼은 피냐를 땅속 구덩이에서 구워 스모키해요.', 'The heart (piña) of a mature agave is cooked, crushed, fermented and usually distilled twice. Mezcal piñas are roasted in earthen pits, hence the smoke.'],
   taste: ['블랑코: 채소·후추·시트러스, 생생한 아가베 / 레포사도: 바닐라·부드러움 / 아네호: 캐러멜·오크. 메스칼: 스모키, 흙, 열대과일.', 'Blanco: vegetal, peppery, citrus / reposado: softer, vanilla / añejo: caramel and oak. Mezcal: smoky, earthy, tropical.'],
   styles: ['블랑코(숙성 없음~2개월 미만), 레포사도(2–12개월), 아네호(1–3년), 엑스트라 아네호(3년+). "100% 아가베"가 아니면 믹스토(아가베 당 51% 이상).', 'Blanco (unaged to under 2 months), reposado (2–12 months), añejo (1–3 years), extra añejo (3+). Without "100% agave" it is a mixto (51%+ agave sugars).'],
   fact: ['병 속 벌레는 테킬라가 아니라 일부 메스칼의 마케팅이에요. 진짜 테킬라에는 넣지 않아요.', 'The worm in the bottle is a marketing gimmick from some mezcals, never tequila.'] },
 { id: 'brandy', ic: '🍇', n: ['브랜디 & 코냑', 'Brandy & Cognac'], base: ['포도 와인(과일 브랜디는 다른 과일)', 'Grape wine (fruit brandies use other fruit)'],
   origin: ['"불에 태운 와인(brandewijn)"이라는 네덜란드어에서 온 이름. 코냑은 프랑스 코냑 지역의 원산지 명칭이에요.', 'From Dutch brandewijn, "burnt wine". Cognac is a protected name from the Cognac region of France.'],
   make: ['코냑은 주로 위니 블랑 포도로 만든 산도 높은 와인을 구리 단식 증류기로 두 번 증류해 프랑스 오크에서 숙성. 아르마냑은 대개 한 번의 연속 증류.', 'Cognac: acidic wine, mostly Ugni Blanc, double-distilled in copper pot stills and aged in French oak. Armagnac usually goes through a single continuous distillation.'],
   taste: ['말린 과일, 바닐라, 꽃, 나무, 향신료. 오래될수록 "랑시오(견과·버섯 같은 숙성 향)".', 'Dried fruit, vanilla, flowers, wood, spice; long ageing brings "rancio" (nutty, earthy).'],
   styles: ['VS: 최소 2년 / VSOP: 최소 4년 / XO: 최소 10년(2018년부터). 칵테일에는 보통 VS·VSOP.', 'VS: at least 2 years / VSOP: 4 / XO: 10 (since 2018). Cocktails usually use VS or VSOP.'],
   fact: ['사제락의 원조 베이스는 코냑. 19세기 말 포도나무 해충(필록세라)이 유럽 포도밭을 휩쓸어 라이 위스키로 바뀌었다고 해요.', 'The Sazerac was originally cognac-based; the phylloxera blight of the late 1800s pushed bars to rye.'] },
 { id: 'triplesec', ic: '🍊', n: ['오렌지 리큐어 (트리플 섹·큐라소)', 'Orange liqueur (triple sec, curaçao)'], base: ['오렌지 껍질 + 주정 + 설탕', 'Orange peel + spirit + sugar'],
   origin: ['큐라소는 카리브해 퀴라소 섬의 쓴 오렌지(라라하)에서 시작. 트리플 섹은 19세기 프랑스에서 나온 맑고 드라이한 스타일. 쿠앵트로는 트리플 섹의 대표 브랜드예요.', 'Curaçao began with the bitter Laraha orange of the island of Curaçao. Triple sec is a clearer, drier French style of the 1800s; Cointreau is its best-known brand.'],
   make: ['말린 오렌지 껍질을 주정에 담그거나 증류해 설탕을 더해요.', 'Dried orange peels are macerated or distilled in spirit, then sweetened.'],
   taste: ['선명한 오렌지 껍질 향, 달콤함. 사워 계열의 "단맛+향" 담당.', 'Bright orange peel and sweetness: the sweet-and-aromatic part of a sour.'],
   styles: ['트리플 섹(맑음), 오렌지 큐라소(앰버, 브랜디 베이스도), 블루 큐라소(색만 파랑).', 'Triple sec (clear), orange curaçao (amber, some brandy-based), blue curaçao (just coloured).'],
   fact: ['블루 큐라소의 파란색은 색소일 뿐, 맛은 오렌지예요.', 'Blue curaçao is only dyed blue; it tastes of orange.'] },
 { id: 'vermouth', ic: '🍷', n: ['베르무트', 'Vermouth'], base: ['와인 + 주정 강화 + 허브(쑥 등)', 'Wine + added spirit + botanicals (wormwood)'],
   origin: ['이름은 독일어 "베르무트(쑥)". 스위트 레드는 18세기 이탈리아 토리노, 드라이는 프랑스 쪽 스타일로 발전했어요.', 'The name comes from German Wermut, wormwood. Sweet red developed in Turin, Italy, in the 18th century; dry in France.'],
   make: ['화이트 와인에 주정을 더해 도수를 15–18%로 올리고, 허브·향신료·뿌리로 향을 내고 설탕(스위트는 많이)을 더해요. 레드 색은 캐러멜 등.', 'White wine fortified to 15–18%, flavoured with herbs, spices and roots, and sweetened (a lot for sweet). The red colour comes from caramel and the like.'],
   taste: ['드라이: 허브·꽃·드라이 / 스위트: 바닐라·체리·쓴 허브·향신료.', 'Dry: herbal, floral, crisp / sweet: vanilla, cherry, bitter herbs, spice.'],
   styles: ['드라이(마티니), 스위트 레드(맨해튼·네그로니), 블랑(달콤한 화이트). 릴레 블랑은 비슷한 "아로마타이즈드 와인".', 'Dry (Martini), sweet red (Manhattan, Negroni), blanc (sweet white). Lillet Blanc is a similar aromatised wine.'],
   fact: ['베르무트는 와인이라 개봉 후 냉장 보관해야 해요. 상온에 몇 달 둔 베르무트가 "마티니가 맛없다"는 오해의 주범.', 'It is wine: refrigerate after opening. Months-old warm vermouth is behind many bad Martinis.'] },
 { id: 'aperitivo', ic: '🔴', n: ['캄파리 & 아페롤 (비터 아페리티보)', 'Campari & Aperol (bitter aperitivo)'], base: ['주정 + 쓴 허브·껍질·뿌리 + 설탕', 'Spirit + bitter herbs, peels, roots + sugar'],
   origin: ['캄파리는 1860년 이탈리아(노바라에서 시작, 밀라노에서 유명). 아페롤은 1919년 파도바.', 'Campari: 1860, Italy (begun in Novara, famed in Milan). Aperol: 1919, Padua.'],
   make: ['비밀 레시피의 허브·과일 껍질을 우려 설탕과 색을 더해요.', 'Secret blends of herbs and peels are infused, sweetened and coloured.'],
   taste: ['캄파리: 강한 쓴맛, 자몽·체리·허브(약 25%) / 아페롤: 더 달고 오렌지향, 가벼움(11%).', 'Campari: intensely bitter, grapefruit, cherry, herbs (about 25%) / Aperol: sweeter, orange, light (11%).'],
   styles: ['"아페리티보" = 식욕을 돋우는 식전주 문화. 쓴맛이 입맛을 깨워요.', '"Aperitivo" is the Italian pre-dinner ritual; bitterness wakes the appetite.'],
   fact: ['캄파리의 붉은색은 예전에 연지벌레(코치닐) 색소였지만 2006년쯤 바뀌었다고 알려져 있어요.', 'Campari’s red once came from cochineal insects; it reportedly switched around 2006.'] },
 { id: 'coffeeliq', ic: '☕', n: ['커피 리큐어', 'Coffee liqueur'], base: ['커피 + 주정(주로 럼·중성 주정) + 설탕', 'Coffee + spirit (often rum or neutral) + sugar'],
   origin: ['대표 브랜드는 1930년대 멕시코에서 시작됐어요.', 'The best-known brand began in 1930s Mexico.'],
   make: ['로스팅한 커피를 주정에 우리고 설탕·바닐라를 더해요.', 'Roasted coffee steeped in spirit, sweetened, often with vanilla.'],
   taste: ['진한 커피, 캐러멜, 바닐라. 꽤 달아요.', 'Rich coffee, caramel, vanilla; quite sweet.'],
   styles: ['달콤한 클래식형, 덜 단 콜드브루형.', 'Sweet classic or drier cold-brew styles.'],
   fact: ['에스프레소 마티니, 블랙/화이트 러시안의 핵심.', 'The heart of the Espresso Martini and Black/White Russian.'] },
 { id: 'maraschino', ic: '🍒', n: ['마라스키노', 'Maraschino'], base: ['마라스카 체리(씨·잎 포함) 증류', 'Distilled marasca cherries (pits and leaves)'],
   origin: ['크로아티아 달마티아 해안(자다르)이 고향.', 'From the Dalmatian coast of Croatia (Zadar).'],
   make: ['체리를 발효·증류해 숙성하고 설탕을 더한 맑은 리큐어.', 'Cherries are fermented, distilled, rested and sweetened into a clear liqueur.'],
   taste: ['빨간 체리 시럽 맛이 아니라 아몬드·꽃·약간 펑키한 체리씨 향. 소량으로 강해요.', 'Not red-cherry syrup: almond, floral, a little funky; powerful in small doses.'],
   styles: ['라스트 워드, 에비에이션, 마르티네즈의 비밀 재료.', 'The secret weapon in the Last Word, Aviation and Martinez.'],
   fact: ['칵테일 체리의 원래 이름 "마라스키노 체리"는 이 리큐어에 절인 체리에서 왔어요.', 'The "maraschino cherry" originally meant cherries preserved in this liqueur.'] },
 { id: 'chartreuse', ic: '🌱', n: ['샤르트뢰즈', 'Chartreuse'], base: ['약 130가지 허브·식물', 'About 130 herbs and plants'],
   origin: ['프랑스 카르투시오 수도회 수도사들이 1605년 받았다고 전해지는 필사본 레시피로 만들어요. 레시피는 소수의 수도사만 안다고 해요.', 'Made by French Carthusian monks from a recipe said to date to a 1605 manuscript; only a few monks are said to know it.'],
   make: ['허브를 우리고 증류·숙성. 그린의 색은 식물 엽록소에서.', 'Herbs macerated, distilled and aged; the green colour comes from plants.'],
   taste: ['그린(55%): 강렬한 허브·민트·소나무, 매운 듯한 / 옐로(40%): 꿀·사프란, 더 부드럽고 달아요.', 'Green (55%): intense herbal, minty, piney / yellow (40%): honey and saffron, softer and sweeter.'],
   styles: ['그린, 옐로, 오래 숙성한 V.E.P.', 'Green, yellow, long-aged V.E.P.'],
   fact: ['수도회는 생산량을 늘리지 않겠다고 밝혀서 품귀 현상이 자주 생겨요.', 'The monks have chosen not to raise production, so shortages are common.'] },
 { id: 'bitters', ic: '💧', n: ['비터스 (앙고스투라·페이쇼드)', 'Bitters (Angostura, Peychaud’s)'], base: ['고도수 주정 + 쓴 뿌리·껍질·향신료', 'High-proof spirit + bitter roots, barks, spices'],
   origin: ['앙고스투라: 1824년 베네수엘라 앙고스투라 마을에서 지게르트 박사가 개발(지금은 트리니다드). 페이쇼드: 1830년대 뉴올리언스 약사 앙투안 페이쇼드.', 'Angostura: created in 1824 by Dr Siegert in Angostura, Venezuela (now made in Trinidad). Peychaud’s: 1830s, New Orleans apothecary Antoine Peychaud.'],
   make: ['약용 "토닉"으로 출발한 진한 추출액. 대시(몇 방울)로 써요.', 'Concentrated extracts that began as medicinal tonics; used by the dash.'],
   taste: ['앙고스투라: 정향·시나몬·쓴 뿌리(약 45%) / 페이쇼드: 아니스·체리, 더 가볍고 붉어요.', 'Angostura: clove, cinnamon, bitter root (about 45%) / Peychaud’s: anise and cherry, lighter and redder.'],
   styles: ['아로마틱, 오렌지, 셀러리, 초콜릿 비터스 등.', 'Aromatic, orange, celery, chocolate and more.'],
   fact: ['앙고스투라의 너무 큰 라벨은 병과 라벨 담당이 따로 만들어서 생긴 실수라는 이야기가 유명해요(전설에 가까움).', 'Angostura’s oversized label is said to come from a mix-up between the bottle and label makers (closer to legend).'] },
 { id: 'absinthe', ic: '🧚', n: ['압생트', 'Absinthe'], base: ['쑥(웜우드) + 아니스 + 펜넬', 'Wormwood + anise + fennel'],
   origin: ['18세기 말 스위스에서 시작, 19세기 프랑스의 "초록 요정". 20세기 초 여러 나라에서 금지됐다가 2000년대에 다시 허용됐어요.', 'Born in late-18th-century Switzerland, the "green fairy" of 19th-century France. Banned in many countries in the early 1900s and legal again in the 2000s.'],
   make: ['허브를 증류하고 일부 허브로 다시 우려 초록색을 내요. 매우 독함(약 45–74%).', 'Herbs are distilled, then some are steeped again for colour. Very strong (about 45–74%).'],
   taste: ['강한 감초·아니스, 허브.', 'Strong liquorice/anise and herbs.'],
   styles: ['칵테일에서는 린스(잔 코팅)나 몇 방울.', 'In cocktails: a rinse or a few drops.'],
   fact: ['"환각을 일으킨다"는 이야기는 근거 없는 신화예요. 문제는 그냥 높은 도수였어요.', 'The hallucination story is a myth; the real issue was simply the strength.'] },
 { id: 'amaro', ic: '🌰', n: ['아마로', 'Amaro'], base: ['주정·그라파 + 쓴 허브·뿌리 + 설탕', 'Spirit or grappa + bitter herbs and roots + sugar'],
   origin: ['이탈리아 식후주 문화. "아마로" = 쓴.', 'The Italian after-dinner tradition; amaro means bitter.'],
   make: ['허브를 우리고 숙성. 노니노 스타일은 그라파 베이스로 오렌지·캐러멜 향.', 'Herbs infused and rested. Nonino-style is grappa-based with orange and caramel notes.'],
   taste: ['쓴맛과 단맛, 허브·오렌지·캐러멜. 브랜드마다 천차만별.', 'Bittersweet with herbs, orange, caramel; hugely varied by brand.'],
   styles: ['가벼운 아페리티보형부터 진한 페르넷형까지.', 'From light aperitivo styles to intense fernet.'],
   fact: ['페이퍼 플레인의 비밀 재료.', 'The secret of the Paper Plane.'] }
];

/* ---------- WHISKY IN DEPTH ---------- */
BAR.WHISKY = [
 { ic: '🏴', t: ['스카치: 기본 규칙', 'Scotch: the rules'], b: ['스코틀랜드에서 증류하고 오크통에서 최소 3년 숙성, 병입 도수 40% 이상. 첨가는 물과 색을 맞추는 캐러멜(E150a)뿐. 표기는 "Whisky" (e 없음).', 'Distilled in Scotland, aged at least 3 years in oak, bottled at 40%+. Only water and caramel colouring (E150a) may be added. Spelled "whisky", no e.'] },
 { ic: '🥇', t: ['싱글 몰트 vs 블렌디드', 'Single malt vs blended'], b: ['싱글 몰트: 한 증류소에서 100% 맥아 보리로, 단식(팟) 증류기로. 블렌디드: 여러 증류소의 몰트 + 가벼운 그레인 위스키를 섞은 것으로 판매량의 대부분. 블렌디드 몰트는 몰트끼리만 섞은 것. "싱글"은 한 통이 아니라 한 증류소라는 뜻이에요.', 'Single malt: 100% malted barley from one distillery, pot stills. Blended: malts from several distilleries plus lighter grain whisky; most of what is sold. Blended malt mixes malts only. "Single" means one distillery, not one cask.'] },
 { ic: '🍎', t: ['스페이사이드', 'Speyside'], b: ['스페이 강 주변, 증류소가 가장 밀집한 지역(공식적으로는 하이랜드 안의 독립 지역). 사과·배·꿀·꽃, 셰리 캐스크면 건포도·크리스마스 케이크. 피트는 대체로 약해요.', 'Around the River Spey, the densest cluster of distilleries (officially its own region within the Highlands). Apple, pear, honey, flowers; sherry casks add raisin and Christmas cake. Usually little peat.'] },
 { ic: '⛰️', t: ['하이랜드', 'Highlands'], b: ['가장 넓은 지역이라 스타일도 다양: 헤더 꿀, 과일, 스파이스, 약한 스모크, 해안가 증류소는 짭짤함.', 'The largest region, so styles vary: heather honey, fruit, spice, gentle smoke, and coastal salinity.'] },
 { ic: '🔥', t: ['아일라 & 피트', 'Islay & peat'], b: ['작은 섬 아일라는 강한 피트 스모크로 유명: 모닥불, 요오드, 바닷바람, 소독약 같은 향. 피트(이탄)를 태워 맥아를 말리면 페놀이 스며들어요. 맥아의 페놀 함량을 ppm으로 표시하며, 강한 아일라 스타일은 대략 40–50ppm대예요(병에서 느끼는 스모크는 증류·숙성으로 줄어요).', 'The small island of Islay is famous for heavy peat smoke: bonfire, iodine, sea spray, medicinal notes. Burning peat to dry malt adds phenols, measured in ppm in the malt; heavy Islay styles sit around 40–50 ppm (less survives distillation and ageing).'] },
 { ic: '🌾', t: ['로우랜드', 'Lowlands'], b: ['가볍고 부드러운 스타일: 풀, 꽃, 시트러스, 비스킷. 역사적으로 3회 증류 전통이 있었어요. 입문용·아페리티프로 좋아요.', 'Light and gentle: grass, flowers, citrus, biscuit. Historically some triple distillation; a good starting point.'] },
 { ic: '⚓', t: ['캠벨타운 & 아일랜즈', 'Campbeltown & Islands'], b: ['캠벨타운: 한때 위스키 수도였지만 지금은 증류소 몇 곳. 짭짤하고 오일리, 살짝 스모키한 독특한 "펑크". 아일랜즈(스카이·오크니·멀 등): 공식적으로는 하이랜드의 일부로, 바다 향과 은은한 스모크가 공통점이지만 섬마다 달라요.', 'Campbeltown: once the whisky capital, now a handful of distilleries; briny, oily, lightly smoky "funk". Islands (Skye, Orkney, Mull…): officially part of the Highlands, sharing sea air and gentle smoke but varying by island.'] },
 { ic: '☘️', t: ['아이리시 위스키', 'Irish whiskey'], b: ['아일랜드 섬에서 최소 3년 숙성. 3회 증류가 흔해 부드럽고 가벼운 편(법적 필수는 아님). 싱글 팟 스틸: 맥아 보리와 맥아하지 않은 생보리를 섞어 단식 증류기로 — 크리미하고 오일리, 스파이시한 아일랜드 고유 스타일.', 'Aged at least 3 years on the island of Ireland. Triple distillation is common (not required), giving a smooth, light style. Single pot still mixes malted and unmalted barley in pot stills: creamy, oily, spicy and uniquely Irish.'] },
 { ic: '🇺🇸', t: ['버번', 'Bourbon'], b: ['미국산, 옥수수 51% 이상, 새로 그을린(charred) 오크통 숙성, 증류 80% 이하·입통 62.5% 이하·병입 40% 이상, 첨가물 금지. 켄터키에서 대부분 만들지만 켄터키일 필요는 없어요. 2년 이상이면 "스트레이트". 새 그을린 통 덕분에 바닐라·캐러멜·코코넛이 진해요.', 'Made in the USA from 51%+ corn, aged in new charred oak, distilled to ≤80%, barrelled at ≤62.5%, bottled at ≥40%, no additives. Most is made in Kentucky, but it need not be. 2+ years = "straight". New charred oak gives big vanilla, caramel, coconut.'] },
 { ic: '🌶️', t: ['라이 & 테네시', 'Rye & Tennessee'], b: ['라이: 호밀 51% 이상(규칙은 버번과 비슷). 후추·허브·드라이, 맨해튼·사제락에 클래식. 테네시: 테네시에서 만들고, 숙성 전에 사탕단풍 숯으로 여과하는 "링컨 카운티 공정"으로 더 부드럽고 달콤해요.', 'Rye: 51%+ rye (rules similar to bourbon); peppery, herbal, drier; classic in the Manhattan and Sazerac. Tennessee: made in Tennessee and filtered through sugar-maple charcoal before ageing (the Lincoln County Process), for a mellower, sweeter style.'] },
 { ic: '🗾', t: ['재패니즈 위스키', 'Japanese whisky'], b: ['1920년대 스코틀랜드 방식을 배워 시작. 섬세하고 균형 잡힌 스타일, 일본 참나무(미즈나라) 통은 백단향·향 같은 향을 줘요. 하이볼 문화가 위스키를 식사와 함께 즐기는 술로 만들었어요. 2021년 업계 기준: 일본에서 발효·증류·3년 이상 숙성·병입해야 "재패니즈 위스키".', 'Started in the 1920s on the Scotch model. Delicate, balanced; Japanese mizunara oak adds sandalwood and incense. Highball culture made whisky a drink for meals. Industry standard (2021): fermented, distilled, aged 3+ years and bottled in Japan to be called Japanese whisky.'] },
 { ic: '🍁', t: ['캐나디안 위스키', 'Canadian whisky'], b: ['캐나다에서 최소 3년 숙성. 곡물별로 따로 증류·숙성해 블렌딩하는 방식이 많아 가볍고 부드러워요. 호밀이 적어도 관습적으로 "라이"라고 부르기도 해요.', 'Aged at least 3 years in Canada. Grains are often distilled and aged separately and blended, for a light, smooth style. Often called "rye" by tradition even with little rye.'] },
 { ic: '🏷️', t: ['라벨 읽기', 'Reading the label'], b: ['숙성 연수(예: 12년)는 병 속 가장 어린 위스키 기준. 연수 표기가 없으면 NAS. 캐스크 스트렝스: 물을 타지 않은 통 원액 도수(대개 50–65%). 논 칠 필터드: 차가운 여과를 하지 않아 질감이 진하고 물을 타면 뿌옇게 될 수 있어요.', 'An age statement (e.g. 12 years) is the youngest whisky in the bottle; none means NAS. Cask strength: undiluted, usually 50–65%. Non-chill-filtered: richer texture, may cloud with water.'] },
 { ic: '🛢️', t: ['캐스크 종류', 'Cask types'], b: ['엑스 버번(아메리칸 오크): 바닐라, 꿀, 코코넛 / 셰리(유러피언 오크): 건포도, 무화과, 견과, 스파이스 / 포트·와인 피니시: 붉은 과일 / 미즈나라: 백단향. 위스키 맛의 큰 부분이 통에서 와요.', 'Ex-bourbon (American oak): vanilla, honey, coconut / sherry (European oak): raisin, fig, nuts, spice / port & wine finishes: red fruit / mizunara: sandalwood. Much of a whisky’s flavour comes from the cask.'] },
 { ic: '👃', t: ['테이스팅 방법', 'How to taste'], b: ['① 튤립형 잔에 조금. ② 색 보기(캐러멜로 맞췄을 수 있어 참고만). ③ 입을 살짝 벌리고 천천히 향 맡기(코를 박으면 알코올이 찔러요). ④ 작게 한 모금, 혀 전체에 굴리기. ⑤ 피니시(여운). ⑥ 물 몇 방울을 넣고 다시: 향이 열리는 경우가 많아요.', '① A little in a tulip glass. ② Look (colour may be adjusted, so only a hint). ③ Nose gently with your mouth slightly open; don’t bury your nose. ④ Small sip, coat the tongue. ⑤ Finish. ⑥ Add a few drops of water and try again; it often opens up.'] }
];

/* ---------- STORIES ---------- lg: 1 = legend / disputed */
BAR.STORY = [
 { r: 'vesper', lg: 0, t: ['본드, 베스퍼, "셰이큰, 낫 스터드"', 'Bond, the Vesper and "shaken, not stirred"'], b: ['이언 플레밍의 1953년 소설 「카지노 로얄」에서 본드는 "고든스 3, 보드카 1, 키나 릴레 반, 얼음처럼 차가워질 때까지 잘 흔들고, 크고 얇은 레몬 껍질"을 주문하고 여주인공 베스퍼 린드의 이름을 붙여요. "셰이큰, 낫 스터드"는 1960년대 영화로 유명해진 대사예요. 정석은 마티니를 젓는 것이라, 흔드는 본드의 취향 자체가 캐릭터예요.', 'In Ian Fleming’s 1953 novel Casino Royale, Bond orders "three measures of Gordon’s, one of vodka, half a measure of Kina Lillet, shaken until ice-cold, with a large thin slice of lemon peel", and names it after Vesper Lynd. "Shaken, not stirred" became famous through the 1960s films. Bartenders stir Martinis, so the shaking is part of Bond’s character.'] },
 { r: 'martini', lg: 1, t: ['마티니의 기원', 'Where the Martini came from'], b: ['1880년대 진·스위트 베르무트·마라스키노의 "마르티네즈"가 조상이라는 설이 유력하지만, 캘리포니아 마르티네즈 마을, 뉴욕 호텔 바텐더 등 여러 주장이 있어요. 20세기를 지나며 베르무트가 줄어 점점 "드라이"해졌어요.', 'A strong theory traces it to the 1880s Martinez (gin, sweet vermouth, maraschino), but the town of Martinez, California, and a New York hotel bartender are also credited. Over the 20th century it grew steadily drier.'] },
 { r: 'negroni', lg: 1, t: ['네그로니 백작', 'Count Negroni'], b: ['전해지는 이야기: 1919년경 피렌체 카페 카소니에서 카밀로 네그로니 백작이 아메리카노를 더 세게 해 달라며 소다 대신 진을 넣게 했고, 바텐더 포스코 스카르셀리는 오렌지 가니시를 얹었어요. 백작의 실존과 연대를 두고 논쟁이 있어 "전설"로 보는 게 안전해요.', 'As the story goes: around 1919 at Caffè Casoni in Florence, Count Camillo Negroni asked for a stronger Americano, gin instead of soda, and bartender Fosco Scarselli added an orange garnish. The count’s biography and dates are debated, so treat it as legend.'] },
 { r: 'marg', lg: 1, t: ['마르가리타는 누가?', 'Who made the first Margarita?'], b: ['티후아나 근처의 카를로스 "대니" 에레라(1938년경)가 증류주 알레르기가 있던 여배우를 위해 만들었다, 아카풀코의 마르가리타 세임스(1948)가 파티에서 만들었다 등 주장이 많아요. 가장 그럴듯한 설명은 기존 "데이지" 칵테일(스피릿+시트러스+오렌지 리큐어)의 테킬라 버전이라는 것. "마르가리타"는 스페인어로 데이지예요. 원조는 미확인.', 'Claims include Carlos "Danny" Herrera near Tijuana (about 1938), for an actress allergic to other spirits, and Margarita Sames at a party in Acapulco (1948). The likeliest explanation: a tequila version of the existing Daisy (spirit + citrus + orange liqueur), and margarita is Spanish for daisy. The true origin is unproven.'] },
 { r: 'mojito', lg: 1, t: ['모히토와 헤밍웨이', 'The Mojito and Hemingway'], b: ['아바나의 바 "라 보데기타 델 메디오" 벽에는 "나의 모히토는 보데기타에서, 나의 다이키리는 플로리디타에서"라는 헤밍웨이 서명 글귀가 걸려 있어요. 하지만 진품인지 의심하는 연구자가 많아요. 헤밍웨이와 엘 플로리디타의 다이키리 인연은 더 잘 기록돼 있어요. 해적 드레이크의 "엘 드라케"가 조상이라는 이야기도 전설이에요.', 'A Havana bar, La Bodeguita del Medio, displays a Hemingway inscription: "My mojito in La Bodeguita, my daiquiri in El Floridita". Many historians doubt it is genuine; his Daiquiris at El Floridita are far better documented. The idea that it descends from Francis Drake’s "El Draque" is also legend.'] },
 { r: 'bloody', lg: 1, t: ['블러디 메리', 'The Bloody Mary'], b: ['파리 "해리스 뉴욕 바"의 바텐더 페르낭 프티오가 1920년대 초에 만들었다고 주장했고, 1930년대 뉴욕 세인트 레지스 호텔에서 양념을 더해 "레드 스내퍼"라는 이름으로 팔았다고 해요. 코미디언 조지 제슬도 자신이 원조라 했어요. 이름의 유래(메리 1세 등)도 확실하지 않아요.', 'Fernand Petiot claimed he created it at Harry’s New York Bar in Paris in the early 1920s, later spicing it up at New York’s St. Regis in the 1930s, where it was sold as the "Red Snapper". Comedian George Jessel also claimed it. The name’s origin (Mary I?) is uncertain too.'] },
 { r: 'maitai', lg: 1, t: ['마이타이: 트레이더 빅 vs 돈 비치', 'Mai Tai: Trader Vic vs Donn Beach'], b: ['트레이더 빅(빅터 버저론)은 1944년 오클랜드의 자기 바에서 타히티 친구들에게 만들어 줬고, 맛본 친구가 "마이타이 로아 아에!(최고야!)"라고 외쳤다고 해요. 돈 더 비치코머(돈 비치)는 1933년 자기 레시피가 먼저라고 주장했지만 재료가 꽤 달라요. 오늘날 IBA 레시피는 트레이더 빅 계열이에요.', 'Trader Vic (Victor Bergeron) said he made it in 1944 at his Oakland bar for Tahitian friends, one of whom cried "Maita’i roa ae!" ("out of this world, the best!"). Donn Beach claimed an earlier 1933 drink, though its recipe was quite different. The IBA spec follows Trader Vic.'] },
 { r: null, lg: 0, t: ['금주법과 스피크이지', 'Prohibition and speakeasies'], b: ['미국은 1920–1933년 술의 제조·판매·운송을 금지했어요(수정헌법 18조, 1933년 21조로 폐지). 몰래 운영하는 "스피크이지"가 번성했고, 조악한 밀주의 맛을 가리려 칵테일을 많이 섞었다는 이야기가 흔해요. 많은 미국 바텐더가 런던·파리·아바나로 떠나 칵테일 문화를 세계에 퍼뜨렸어요. 이 게임의 분위기도 그 시대 스피크이지에서 따왔어요.', 'From 1920 to 1933 the US banned making, selling and transporting alcohol (18th Amendment, repealed by the 21st). Hidden "speakeasies" thrived, and cocktails are often said to have masked rough bootleg spirits. Many American bartenders left for London, Paris and Havana and spread cocktail culture worldwide, the era this bar’s look is borrowed from.'] },
 { r: 'ofash', lg: 0, t: ['"칵테일"의 첫 정의 (1806)', 'The first definition of "cocktail" (1806)'], b: ['1806년 뉴욕주 허드슨의 신문 「밸런스 앤 컬럼비안 리포지터리」는 칵테일을 "어떤 종류든 스피릿, 설탕, 물, 비터스로 만든 자극적인 술"이라고 설명했어요. 19세기 후반 화려한 칵테일이 늘자 손님들이 "옛날 방식(old-fashioned)"으로 달라고 한 데서 이름이 나왔다고 해요.', 'In 1806 The Balance and Columbian Repository of Hudson, New York, described a cocktail as "a stimulating liquor, composed of spirits of any kind, sugar, water, and bitters". When fancier drinks spread in the late 1800s, guests asked for one the "old-fashioned" way.'] },
 { r: 'mule', lg: 0, t: ['모스코 뮬과 구리 머그 마케팅', 'The Moscow Mule and the copper mug'], b: ['1940년대 초 로스앤젤레스. 안 팔리는 보드카를 가진 주류 회사 사람과 안 팔리는 진저 비어를 가진 바 주인이 손을 잡고 만든 술로 알려져 있어요. 구리 머그와 즉석 사진으로 바텐더들을 홍보한 마케팅 덕분에 미국에 보드카 붐이 일었어요. 세부 등장인물은 이야기마다 조금씩 달라요.', 'Los Angeles, early 1940s: a spirits man with unsold vodka and a bar owner with unsold ginger beer teamed up, so the story goes. The copper mug and instant photos of bartenders holding it fuelled America’s vodka boom. The cast of characters varies by telling.'] },
 { r: 'irish', lg: 0, t: ['아이리시 커피, 포인스 공항', 'Irish Coffee at Foynes'], b: ['1940년대 초 아일랜드 포인스의 비행정 터미널. 악천후로 회항해 추위에 떤 승객들에게 셰프 조 셰리던이 커피에 위스키와 설탕, 크림을 얹어 냈어요. "브라질 커피냐"는 질문에 "아이리시 커피"라고 답했다고 해요. 이후 섀넌 공항으로, 1952년 샌프란시스코 부에나 비스타 카페로 건너가 세계적으로 유명해졌어요.', 'Foynes flying-boat terminal, Ireland, early 1940s: chef Joe Sheridan gave chilled passengers of a returned flight coffee with whiskey, sugar and cream. Asked if it was Brazilian coffee, he said it was Irish coffee. It moved to Shannon Airport, then in 1952 to the Buena Vista Cafe in San Francisco and fame.'] },
 { r: 'espresso', lg: 1, t: ['에스프레소 마티니, 런던', 'The Espresso Martini, London'], b: ['1980년대 런던 소호의 전설적인 바텐더 딕 브래드셀의 작품. 유명 모델이 "잠을 깨우고, 그다음엔 취하게 해 줄" 술을 달라고 했다는 일화가 전해지지만 세부는 전설이에요. 처음 이름은 "보드카 에스프레소"였어요. 브래드셀은 브램블도 만들었어요.', 'Created by legendary London bartender Dick Bradsell in 1980s Soho. A famous model is said to have asked for something to "wake me up" and then get her drunk; the details are legend. It was first called the Vodka Espresso. Bradsell also created the Bramble.'] },
 { r: 'daiq', lg: 1, t: ['다이키리 광산', 'The Daiquirí mine'], b: ['쿠바 산티아고 근처 다이키리 광산에서 일하던 미국인 기술자 제닝스 콕스가 1900년 전후 만들었다는 이야기가 유명해요. 사실 쿠바에는 럼+라임+설탕 조합이 이미 흔했어요. 헤밍웨이는 엘 플로리디타에서 설탕 없는 더블 다이키리를 즐겼다고 해요.', 'The popular story credits Jennings Cox, an American engineer at the Daiquirí mine near Santiago de Cuba, around 1900; in truth rum, lime and sugar were already common in Cuba. Hemingway favoured a sugarless double at El Floridita.'] },
 { r: 'sazerac', lg: 0, t: ['사제락, 뉴올리언스', 'The Sazerac, New Orleans'], b: ['1830년대 뉴올리언스의 약사 앙투안 페이쇼드가 만든 비터스와, 사제락 커피하우스에서 쓰던 코냑 이름에서 탄생. 필록세라 이후 라이 위스키로, 1912년 미국의 압생트 금지 후엔 대체 아니스 리큐어로 린스했어요. 2008년 루이지애나 주가 뉴올리언스 공식 칵테일로 지정. "칵테일이라는 말이 계란 컵(coquetier)에서 왔다"는 이야기는 신화예요.', 'Born from the bitters of 1830s New Orleans apothecary Antoine Peychaud and the cognac served at the Sazerac Coffee House. After phylloxera it switched to rye, and after the US banned absinthe in 1912, other anise liqueurs did the rinse. Louisiana named it New Orleans’ official cocktail in 2008. The claim that "cocktail" comes from the egg cup coquetier is a myth.'] },
 { r: 'gt', lg: 0, t: ['진토닉과 말라리아', 'The G&T and malaria'], b: ['19세기 영국령 인도에서 말라리아 예방용 키니네(기나나무 껍질)의 쓴맛을 줄이려 탄산수·설탕·라임·진과 섞어 마신 것이 시작이라고 해요. 큰 흐름은 사실이지만 단순화된 이야기예요. 오늘날 토닉의 키니네는 아주 적어서 약효는 없어요.', 'In 19th-century British India, bitter quinine (from cinchona bark) taken against malaria was made palatable with soda, sugar, lime and gin. Broadly true but simplified; modern tonic contains far too little quinine to be medicinal.'] },
 { r: 'pina', lg: 1, t: ['피냐 콜라다, 푸에르토리코', 'Piña Colada, Puerto Rico'], b: ['산후안의 카리브 힐튼 호텔은 1954년 바텐더 라몬 "몬치토" 마레로가 만들었다고 하고, 바라치나 레스토랑은 1963년 자기네가 원조라고 해요. 통조림 코코넛 크림이 나오면서 가능해진 술이에요. 1978년 푸에르토리코 국민 음료로 지정.', 'San Juan’s Caribe Hilton says bartender Ramón "Monchito" Marrero created it in 1954; the Barrachina restaurant claims 1963. Canned cream of coconut made it possible. Named Puerto Rico’s national drink in 1978.'] },
 { r: 'cosmo', lg: 1, t: ['코스모폴리탄', 'The Cosmopolitan'], b: ['1980년대 마이애미 사우스 비치의 셰릴 쿡, 1988년 뉴욕 오데온의 토비 체키니(생라임+쿠앵트로로 다듬음) 등 여러 원조 주장이 있어요. 1990년대 말 드라마 「섹스 앤 더 시티」로 세계적인 아이콘이 됐어요.', 'Claims include Cheryl Cook in 1980s South Beach, Miami, and Toby Cecchini at New York’s Odeon in 1988 (who refined it with fresh lime and Cointreau). Sex and the City made it a global icon in the late 1990s.'] },
 { r: 'lastword', lg: 0, t: ['라스트 워드의 부활', 'The Last Word’s revival'], b: ['금주법 직전 디트로이트 애슬레틱 클럽에서 처음 기록된 술. 수십 년 잊혔다가 2004년경 시애틀 지그재그 카페의 바텐더 머리 스텐슨이 옛 책에서 찾아내 다시 유행시켰어요. 현대 "이퀄 파트" 칵테일 붐의 출발점.', 'First recorded at the Detroit Athletic Club just before Prohibition, then forgotten for decades until Murray Stenson of Seattle’s Zig Zag Café revived it from an old book around 2004, kicking off the modern equal-parts craze.'] },
 { r: 'penicillin', lg: 0, t: ['페니실린과 페이퍼 플레인', 'The Penicillin and the Paper Plane'], b: ['둘 다 샘 로스의 작품. 페니실린은 2005년 뉴욕 바 "밀크 앤 허니"에서, 페이퍼 플레인은 2007년 시카고 바 개업을 위해 만들었고 노래 제목에서 이름을 땄어요(처음엔 캄파리, 곧 아페롤로). 21세기에 탄생해 IBA에 오른 "뉴 클래식".', 'Both by Sam Ross: the Penicillin in 2005 at New York’s Milk & Honey, the Paper Plane in 2007 for a Chicago bar opening, named after a song (first with Campari, soon Aperol). 21st-century drinks that made the IBA list as "new era" classics.'] },
 { r: 'jhigh', lg: 0, t: ['일본의 하이볼 문화', 'Japan’s highball culture'], b: ['1950년대 저렴한 위스키 바가 퍼지며 하이볼이 대중화됐고, 2008년 무렵 대형 위스키 회사의 캠페인으로 "식사와 함께 마시는 하이볼" 붐이 다시 일었어요. 차가운 잔, 단단한 얼음, 강한 탄산, 한 번만 젓기 — 단순함 속의 정밀함이 핵심.', 'Highballs went mainstream with cheap whisky bars in the 1950s, and a big distiller’s campaign around 2008 sparked a new boom of highballs with meals. Cold glass, hard ice, lively soda, one gentle stir: precision in simplicity.'] },
 { r: 'f75', lg: 1, t: ['프렌치 75와 대포', 'The French 75 and the field gun'], b: ['1차 세계대전 프랑스의 75mm 야포처럼 "한 방"이 세다는 데서 이름이 왔다고 해요. 1920년대 칵테일 책에 실리며 유명해졌어요. 처음엔 진이었는지 코냑이었는지도 논쟁거리.', 'Named, so they say, for the kick of France’s WWI 75 mm field gun; 1920s cocktail books made it famous. Whether it began with gin or cognac is still argued.'] },
 { r: 'julep', lg: 0, t: ['민트 줄렙과 켄터키 더비', 'The Mint Julep and the Kentucky Derby'], b: ['남부의 아침 술로 시작해 1938년부터 켄터키 더비의 공식 음료가 됐어요. 경기 주말에만 수십만 잔이 팔린다고 해요. 은잔에 서리가 맺힐 때까지 젓는 게 전통.', 'A Southern morning drink that became the official drink of the Kentucky Derby in 1938; well over a hundred thousand are served over race weekend. Stirred in a silver cup until it frosts.'] }
];

/* ---------- PRO TIPS ---------- */
BAR.TIPS = [
 ['지거 vs 프리 푸어', 'Jigger vs free pour', '지거는 매번 같은 맛과 원가 관리를 보장해요. 프리 푸어(포어러를 끼우고 숫자를 세며 붓기)는 빠르지만 꾸준히 지거로 검증해야 정확해요. 칵테일 바는 대부분 지거를 써요.', 'A jigger guarantees consistency and cost control. Free pouring (counting with a pour spout) is fast but must be checked against a jigger regularly. Most cocktail bars jigger.'],
 ['흔들까, 저을까', 'Shake or stir?', '시트러스·주스·유제품·달걀 → 셰이크(섞고, 차갑게, 공기를 넣어 가볍게). 스피릿·베르무트·비터스만 → 스터(투명하고 매끈하게). 예외: 본드의 베스퍼.', 'Citrus, juice, dairy or egg → shake (mix, chill, aerate). Spirits, vermouth and bitters only → stir (clear and silky). The exception: Bond’s Vesper.'],
 ['희석도 재료다', 'Dilution is an ingredient', '얼음이 녹은 물이 알코올의 날을 다듬어요. 흔들거나 저은 칵테일에는 대략 20–30%의 물이 더해져요(얼음·시간에 따라 다름). 너무 짧으면 뜨겁고 독하고, 너무 길면 밍밍해요.', 'Meltwater smooths the alcohol. Shaken or stirred drinks gain very roughly 20–30% water, depending on ice and time. Too short tastes hot and harsh, too long tastes watery.'],
 ['얼음이 맛을 좌우한다', 'Ice quality matters', '단단하고 차갑고 마른 얼음을 넉넉히. 젖은 작은 얼음은 빨리 녹아요. 셰이커에서 쓴 얼음은 잔에 붓지 말고 새 얼음 위에 걸러요.', 'Use plenty of hard, cold, dry ice; small wet ice melts fast. Never dump shaker ice into the glass; strain over fresh ice.'],
 ['잔 칠링', 'Chill the glass', '업으로 내는 술은 잔에 얼음물을 먼저 채워 두었다가 버리고 따라요(혹은 냉동고 보관). 따뜻한 잔은 몇 초 만에 술을 미지근하게 만들어요.', 'For drinks served up, fill the glass with ice water first and dump it before straining (or keep glasses in the freezer). A warm glass ruins a cold drink in seconds.'],
 ['시트러스 오일 짜기', 'Express citrus oils', '필의 껍질 면을 술 쪽으로 향하게 잡고 잔 위에서 꾹 접어 짜면 오일이 안개처럼 뿌려져요. 림을 한 바퀴 문지른 뒤 넣거나 버려요. 마티니·올드 패션드의 향의 절반.', 'Hold the peel skin-side towards the drink and pinch it over the glass to mist the oils, rub the rim, then drop it in or discard. Half the aroma of a Martini or Old Fashioned.'],
 ['미장 플라스', 'Mise en place', '영업 전에 시트러스 착즙(가급적 당일), 시럽 라벨링, 가니시 손질, 도구 위치 고정. 바쁠 때 손이 "생각 없이" 움직이게 준비하는 것이 실력이에요. 일하면서 바로바로 치워요.', 'Before service: juice citrus (same day), label syrups, prep garnishes, fix every tool’s place, so your hands move without thinking during the rush. Clean as you go.'],
 ['싼 재료부터 넣기', 'Cheapest first', '시럽·시트러스처럼 싼 재료를 먼저, 스피릿은 마지막에. 실수하면 비싼 술을 버리지 않아도 돼요. 얼음은 다 넣은 뒤 마지막에(먼저 넣으면 희석이 시작돼요).', 'Syrup and citrus first, spirits last, so a mistake doesn’t waste expensive liquor. Ice goes in last; dilution starts the moment it touches the liquid.'],
 ['내기 전에 맛보기', 'Taste before serving', '빨대를 살짝 담갔다 손가락으로 막아 들어 맛봐요. 바텐더는 절대 틴에 입을 대지 않아요.', 'Dip a straw, cap it with a finger, lift and taste. Never drink from the tin.'],
 ['셰이크 자세', 'Shaking technique', '틴을 꽉 결합하고 두 손으로 잡아 어깨 높이에서 힘차게 10–15초. 틴 겉면에 서리가 끼면 충분히 차가워진 신호.', 'Seal the tins, hold with both hands and shake hard at shoulder height for 10–15 seconds. Frost on the tin means it is cold.'],
 ['스터 자세', 'Stirring technique', '바스푼 등을 잔 안쪽 벽에 붙이고 손가락으로 부드럽게 돌려요. 얼음과 스푼이 한 덩어리처럼 조용히 돌아야 해요. 소리가 나면 너무 거칠어요.', 'Keep the back of the spoon against the inside wall and turn it smoothly with your fingers; ice and spoon should rotate as one, quietly. Clattering means too rough.'],
 ['더블 스트레인', 'Double strain', '업으로 내는 셰이크 칵테일은 호손 스트레이너 + 고운 체로 걸러 얼음 조각과 허브 찌꺼기를 없애요. 질감이 비단처럼.', 'For shaken drinks served up, use a Hawthorne plus a fine strainer to catch ice shards and herb bits for a silky texture.'],
 ['탄산 지키기', 'Keep the fizz', '믹서는 차갑게, 작은 병으로, 열자마자. 바스푼을 타고 얼음 사이로 붓고, 한두 번 들어 올리듯만 저어요.', 'Mixers cold, small bottles, freshly opened. Pour down a bar spoon between the cubes and lift once or twice.'],
 ['달걀흰자', 'Egg white', '신선한(가능하면 살균) 달걀을 쓰고, 드라이 셰이크 후 얼음 셰이크. 거품 위에 비터스 몇 방울로 장식할 수 있어요.', 'Use fresh (ideally pasteurised) eggs; dry shake, then shake with ice. A few drops of bitters can decorate the foam.'],
 ['러시 속도 내기', 'Speed in a rush', '티켓을 기법별로 묶어요(셰이크끼리, 빌드끼리). 양손으로 동시에 따르고, 틴 여러 개를 줄 세워 한 번에 흔들어요.', 'Group tickets by technique (shakes together, builds together). Pour with both hands and line up several tins to shake at once.'],
 ['표준 잔(스탠더드 드링크)', 'Standard drinks', '나라마다 기준이 달라요: WHO는 순수 알코올 10g, 미국은 14g, 영국 "유닛"은 8g. 40% 스피릿 45ml에는 약 14g이 들어 있어요. 롱 아일랜드 한 잔은 그 1.5배 이상!', 'Definitions vary: WHO uses 10 g of pure alcohol, the US 14 g, a UK unit 8 g. 45 ml of a 40% spirit holds about 14 g; a Long Island holds over 1.5 times that.'],
 ['책임 있는 서비스', 'Responsible service', '물을 함께 내고(워터 백), 음식을 권하고, 취한 손님에게는 정중히 더 이상 내지 않아요. 좋은 바텐더는 손님이 안전하게 집에 가는 것까지 책임져요.', 'Serve water alongside, suggest food, and politely stop serving intoxicated guests. A good bartender cares that guests get home safely.']
];

